// Input: 13 masks, low/high bit of each label-pair chosen later (orbit orientation is variable); enumerate orientations preserving label-pair multiplicities. Only finished feasible templates emitted. Stops after specified number of complete forced-blue survivors per skeleton, so counts conditional on budget. No endpoint input.
use std::io::{self,BufRead};fn sw(x:u32)->u32{((x&85)<<1)|((x&170)>>1)}fn impossible(m:&[u32],blue:&[u32],p:u32,k:u32,u:u32)->bool{limited(m,blue,p,k,u,8)}fn limited(m:&[u32],blue:&[u32],mut p:u32,k:u32,u:u32,limit:u32)->bool{if u.count_ones()>limit{return false}if k>u.count_ones().min(7){return true}while k+p.count_ones()>u.count_ones().min(7){let i=p.trailing_zeros()as usize;p&=p-1;if limited(m,blue,p&blue[i],k+1,u|m[i],limit){return true}}false}fn base(m:&[u32])->Vec<u32>{m.iter().enumerate().map(|(i,s)|m.iter().enumerate().filter(|&(j,v)|i!=j&&s&v!=0).fold(0,|x,(j,_)|x|1<<j)).collect()}
pub fn propagate(m:&[u32],limit:u32)->(u32,usize){let f=(1<<26)-1;let mut red=[0u32;26];let mut blue=base(m);for step in 0..326{let mut change=false;for i in 0..26{if red[i].count_ones()>8-m[i].count_ones(){return(2,step)}for j in 0..i{if red[i]&red[j]!=0||red[i].count_ones()==8-m[i].count_ones()&&red[i]>>j&1==0||red[j].count_ones()==8-m[j].count_ones()&&red[j]>>i&1==0{if red[i]>>j&1!=0{return(3,step)}blue[i]|=1<<j;blue[j]|=1<<i}}}if limited(m,&blue,f,0,0,limit){return(4,step)}for i in 0..26{let avail=f&!(blue[i]|1<<i);if avail.count_ones()<8-m[i].count_ones(){return(5,step)}for j in 0..26{if avail>>j&1==0||red[i]>>j&1!=0{continue}if avail.count_ones()==8-m[i].count_ones()||limited(m,&blue,blue[i]&blue[j],2,m[i]|m[j],limit){red[i]|=1<<j;red[j]|=1<<i;change=true}}}if !change{return(0,step)}}unreachable!()}
fn rec(id:usize,opts:&[Vec<u32>],m:&mut Vec<u32>,st:&mut [usize;9],lim:usize){if st[0]>=lim||st[1]>=50000{return}if id==13{st[0]+=1;let(v,_)=propagate(m,8);st[2+v as usize]+=1;if v==0{println!("{}",m.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(" "))}return}for &s in &opts[id]{st[1]+=1;m.extend([s,sw(s)]);let blue=base(m);let n=m.len();let bad=(n-2..n).any(|i|impossible(m,&blue,blue[i],1,m[i]));if !bad{rec(id+1,opts,m,st,lim)}m.truncate(n-2);if st[0]>=lim||st[1]>=50000{return}}}
fn main(){let lim=std::env::args().nth(1).unwrap().parse().unwrap();for l in io::stdin().lock().lines(){let a:Vec<u32>=l.unwrap().split_whitespace().map(|v|v.parse().unwrap()).collect();let os:Vec<_>=a.iter().map(|&v|{let first=v.min(sw(v));let mut row=vec![first];for s in 1..256{if s!=first&&s<=sw(s)&&(0..4).all(|j|((s>>(2*j))&3u32).count_ones()==((v>>(2*j))&3).count_ones()){row.push(s)}}row}).collect();let mut st=[0;9];rec(0,&os,&mut vec![],&mut st,lim);eprintln!("{:?}",st)}}
